def countEqualSumPairs(nums):
    MOD = 1_000_000_007
    total = sum(nums)
    off = total
    ways = [0] * (2 * total + 1)
    ways[off] = 1
    for x in nums:
        new = ways[:]
        for d in range(2 * total + 1):
            w = ways[d]
            if w:
                if d + x <= 2 * total:
                    new[d + x] = (new[d + x] + w) % MOD
                if d - x >= 0:
                    new[d - x] = (new[d - x] + w) % MOD
        ways = new
    return (ways[off] - 1) % MOD
